public class Guard : GameComponent {
    private float x;
    public Guard(Game game) : base(game) { }
    public override void Update(GameTime gameTime) {
        x += 20f * (float)gameTime.ElapsedGameTime.TotalSeconds;
        base.Update(gameTime);
    }
}
